<?php
namespace App\Http\Controllers\Patient;
use App\Http\Controllers\Controller;use App\Services\LegacyMedicalCodeService;use App\Services\Auth\LegacyAuditService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class PatientController extends Controller {public function __construct(private LegacyMedicalCodeService $codes,private LegacyAuditService $audit){}private function db($e){return response()->json(['message'=>'Database error','error'=>$e->getMessage()],500);}private function branchMap($ids){$map=[];if(!$ids)return $map;$rows=DB::table('patient_branch as pb')->join('branch as b','b.id','=','pb.branch_id')->whereIn('pb.patient_id',$ids)->whereNull('pb.deleted_at')->whereNull('b.deleted_at')->select('pb.patient_id','b.id as branch_id','b.name as branch_name','b.code as branch_code')->orderBy('b.name')->get();foreach($rows as $r){$map[$r->patient_id][]=(object)['id'=>(int)$r->branch_id,'name'=>$r->branch_name,'code'=>$r->branch_code];}return $map;}private function attach($patients){$patients=is_array($patients)?$patients:($patients?$patients:[]);if(!$patients)return $patients;$map=$this->branchMap(array_map(fn($p)=>$p->id,$patients));foreach($patients as $p){$bs=$map[$p->id]??[];$p->branch_ids=array_map(fn($b)=>$b->id,$bs);$p->branches=$bs;$p->branch_names=implode(', ',array_map(fn($b)=>$b->name,$bs));}return $patients;}private function enrich($ids=null,$filterDeleted=true){$q=DB::table('patient as p')->leftJoin('users as u','p.user_id','=','u.id')->select('p.*','u.username','u.status as user_status');if($filterDeleted)$q->whereNull('p.deleted_at');if($ids)$q->whereIn('p.id',(array)$ids);return $this->attach($q->orderByDesc('p.created_at')->get()->all());}public function index(){try{return response()->json(['message'=>'Patients fetched successfully','data'=>$this->enrich()]);}catch(\Throwable $e){return $this->db($e);}}public function show($id){try{$x=$this->enrich([$id],false);return count($x)?response()->json(['message'=>'Patient fetched successfully','data'=>$x[0]]):response()->json(['message'=>'Patient not found'],404);}catch(\Throwable $e){return $this->db($e);}}public function nextCode(){try{return response()->json(['message'=>'Next patient code generated successfully','data'=>['code'=>$this->codes->next('patient')]]);}catch(\Throwable $e){return $this->db($e);}}public function store(Request $r){if(!$r->input('full_name')||!$r->input('phone'))return response()->json(['message'=>'Full name and phone are required'],400);try{$code=$this->codes->next('patient');$id=DB::table('patient')->insertGetId($this->data($r)+['patient_code'=>$code,'status'=>'active']);$this->sync($id,$r->input('branch_ids'));$this->audit->log($r,'PATIENT_CREATE','patient',$id,['patient_code'=>$code]);return response()->json(['message'=>'Patient created successfully','data'=>['id'=>$id,'patient_code'=>$code,'full_name'=>$r->input('full_name'),'phone'=>$r->input('phone'),'branch_ids'=>$r->input('branch_ids',[])]],201);}catch(\Throwable $e){return response()->json(['message'=>'Failed to create patient','error'=>$e->getMessage()],500);}}public function update(Request $r,$id){if(!$r->input('full_name')||!$r->input('phone'))return response()->json(['message'=>'Full name and phone are required'],400);try{$n=DB::table('patient')->where('id',$id)->update($this->data($r)+['status'=>$r->input('status','active'),'updated_at'=>now()]);if(!$n)return response()->json(['message'=>'Patient not found'],404);$this->sync($id,$r->input('branch_ids'));$this->audit->log($r,'PATIENT_UPDATE','patient',$id);return response()->json(['message'=>'Patient updated successfully']);}catch(\Throwable $e){return $this->db($e);}}public function destroy(Request $r,$id){try{$n=DB::table('patient')->where('id',$id)->whereNull('deleted_at')->update(['deleted_at'=>now(),'updated_at'=>now()]);if(!$n)return response()->json(['message'=>'Patient not found'],404);DB::table('patient_branch')->where('patient_id',$id)->whereNull('deleted_at')->update(['deleted_at'=>now()]);$this->audit->log($r,'PATIENT_DELETE','patient',$id);return response()->json(['message'=>'Patient deleted successfully']);}catch(\Throwable $e){return $this->db($e);}}public function me(Request $r){try{$x=DB::table('patient as p')->leftJoin('users as u','p.user_id','=','u.id')->select('p.*','u.username','u.email as user_email','u.status as user_status')->where('p.user_id',$r->attributes->get('legacy_auth_user')->id)->where(fn($q)=>$q->where('p.status','<>','blocked')->orWhereNull('p.status'))->first();if(!$x)return response()->json(['message'=>'Patient profile not found'],404);$this->attach([$x]);return response()->json(['message'=>'Patient profile fetched successfully','data'=>$x]);}catch(\Throwable $e){return $this->db($e);}}public function updateMe(Request $r){$uid=$r->attributes->get('legacy_auth_user')->id;if(!$r->input('full_name')||!$r->input('phone'))return response()->json(['message'=>'Full name and phone are required'],400);$n=DB::table('patient')->where('user_id',$uid)->where(fn($q)=>$q->where('status','<>','blocked')->orWhereNull('status'))->update($this->data($r)+['updated_at'=>now()]);if(!$n)return response()->json(['message'=>'Patient profile not found'],404);$this->audit->log($r,'PATIENT_PROFILE_UPDATE','patient',null,['user_id'=>$uid]);return response()->json(['message'=>'Patient profile updated successfully']);}public function myBranches(Request $r){try{$pid=$this->pid($r);if(!$pid)return response()->json(['message'=>'Patient profile not found'],404);$appt=DB::select("SELECT b.id,b.name,b.city,b.address,b.phone,b.email,COUNT(DISTINCT a.id) AS appointment_count,MAX(a.appointment_date) AS last_appointment_date FROM appointment a JOIN doctor_branch db ON a.doctor_id=db.doctor_id JOIN branch b ON db.branch_id=b.id WHERE a.patient_id=? AND (db.deleted_at IS NULL) AND b.deleted_at IS NULL GROUP BY b.id,b.name,b.city,b.address,b.phone,b.email ORDER BY last_appointment_date DESC",[$pid]);$cons=DB::select("SELECT b.id,b.name,b.city,b.address,b.phone,b.email,COUNT(DISTINCT c.id) AS consultation_count,MAX(c.created_at) AS last_consultation_date FROM consultation c JOIN doctor_branch db ON c.doctor_id=db.doctor_id JOIN branch b ON db.branch_id=b.id WHERE c.patient_id=? AND c.doctor_id IS NOT NULL AND (db.deleted_at IS NULL) AND b.deleted_at IS NULL GROUP BY b.id,b.name,b.city,b.address,b.phone,b.email ORDER BY last_consultation_date DESC",[$pid]);return response()->json(['message'=>'My branches fetched successfully','data'=>['appointments'=>$appt,'consultations'=>$cons]]);}catch(\Throwable $e){return $this->db($e);}}
public function myDoctors(Request $r){try{$pid=$this->pid($r);if(!$pid)return response()->json(['message'=>'Patient profile not found'],404);$appt=DB::select("SELECT d.id,d.full_name,d.avatar_url,s.name AS specialty_name,COUNT(a.id) AS appointment_count,MAX(a.appointment_date) AS last_appointment_date FROM appointment a JOIN doctor d ON a.doctor_id=d.id LEFT JOIN specialty s ON d.specialty_id=s.id WHERE a.patient_id=? GROUP BY d.id,d.full_name,d.avatar_url,s.name ORDER BY last_appointment_date DESC",[$pid]);$cons=DB::select("SELECT d.id,d.full_name,d.avatar_url,s.name AS specialty_name,COUNT(c.id) AS consultation_count,MAX(c.created_at) AS last_consultation_date FROM consultation c JOIN doctor d ON c.doctor_id=d.id LEFT JOIN specialty s ON d.specialty_id=s.id WHERE c.patient_id=? AND c.doctor_id IS NOT NULL GROUP BY d.id,d.full_name,d.avatar_url,s.name ORDER BY last_consultation_date DESC",[$pid]);return response()->json(['message'=>'My doctors fetched successfully','data'=>['appointments'=>$appt,'consultations'=>$cons]]);}catch(\Throwable $e){return $this->db($e);}}
public function stats(Request $r){try{$pid=$this->pid($r);if(!$pid)return response()->json(['message'=>'Patient profile not found'],404);$up=DB::table('appointment')->where('patient_id',$pid)->whereIn('status',['confirmed','pending'])->where('appointment_date','>=',now()->format('Y-m-d'))->count();$pc=DB::table('consultation')->where('patient_id',$pid)->where('status','completed')->count();return response()->json(['message'=>'Stats fetched successfully','data'=>['upcomingAppointments'=>$up,'pastConsultations'=>$pc]]);}catch(\Throwable $e){return $this->db($e);}}
public function ownerBranches(Request $r){try{$uid=$r->attributes->get('legacy_auth_user')->id;$bids=DB::table('branch')->where('owner_user_id',$uid)->whereNull('deleted_at')->pluck('id')->all();if(!$bids)return response()->json(['message'=>'No patients found','data'=>[]]);$rows=DB::table('patient as p')->join('patient_branch as pb','pb.patient_id','=','p.id')->whereIn('pb.branch_id',$bids)->whereNull('pb.deleted_at')->where('p.status','<>','blocked')->distinct()->select('p.id','p.patient_code','p.full_name','p.phone','p.email','p.gender','p.date_of_birth','p.blood_group','p.status','p.created_at')->orderBy('p.full_name')->get()->all();if(!$rows)return response()->json(['message'=>'No patients found','data'=>[]]);return response()->json(['message'=>'Patients fetched successfully','data'=>$this->attach($rows)]);}catch(\Throwable $e){return $this->db($e);}}
private function pid(Request $r){return DB::table('patient')->where('user_id',$r->attributes->get('legacy_auth_user')->id)->value('id');}private function sync($id,$ids){if(!is_array($ids))return;DB::table('patient_branch')->where('patient_id',$id)->delete();foreach($ids as $b)DB::table('patient_branch')->insert(['patient_id'=>$id,'branch_id'=>$b]);}private function data($r){return ['full_name'=>$r->input('full_name'),'phone'=>$r->input('phone'),'email'=>$r->input('email'),'gender'=>$r->input('gender'),'date_of_birth'=>$r->input('date_of_birth'),'address'=>$r->input('address'),'blood_group'=>$r->input('blood_group'),'allergies'=>$r->input('allergies'),'medical_history'=>$r->input('medical_history'),'emergency_contact_name'=>$r->input('emergency_contact_name'),'emergency_contact_phone'=>$r->input('emergency_contact_phone')];}}
